"use strict";

const { readFileSync, writeFileSync } = require("node:fs");
const { join } = require("node:path");

const modules = [
  ["./WerkbonConfig", "WerkbonConfig.js"],
  ["./HubSpotTicketClient", "HubSpotTicketClient.js"],
  ["./DocumensoClient", "DocumensoClient.js"],
  ["./QvantumWerkbonStart", "QvantumWerkbonStart.js"],
];

function rewriteLocalRequires(source) {
  return source.replace(
    /require\((["'])\.\/(WerkbonConfig|HubSpotTicketClient|DocumensoClient|QvantumWerkbonStart)\1\)/g,
    (_match, _quote, moduleName) => `__bundleRequire("./${moduleName}")`,
  );
}

const factories = modules.map(([moduleId, filename]) => {
  const source = rewriteLocalRequires(readFileSync(join(__dirname, filename), "utf8"));
  return `${JSON.stringify(moduleId)}: function(module, exports, __bundleRequire) {\n${source}\n}`;
});

const bundle = `"use strict";

// Generated by build-runtime-bundle.js. Do not edit this file directly.
const __moduleFactories = {
${factories.join(",\n")}
};
const __moduleCache = Object.create(null);
function __bundleRequire(moduleId) {
  if (__moduleCache[moduleId]) return __moduleCache[moduleId].exports;
  const factory = __moduleFactories[moduleId];
  if (!factory) throw new Error(\`Bundled module not found: \${moduleId}\`);
  const bundledModule = { exports: {} };
  __moduleCache[moduleId] = bundledModule;
  factory(bundledModule, bundledModule.exports, __bundleRequire);
  return bundledModule.exports;
}

module.exports = __bundleRequire("./QvantumWerkbonStart");
`;

writeFileSync(join(__dirname, "QvantumWerkbonRuntime.js"), bundle, "utf8");
